public class ConstructorReturnDemo {
    int value;
    ConstructorReturnDemo(boolean skip){ if(skip) return; value=7; }
    public static void main(String[] args){
        System.out.println(new ConstructorReturnDemo(true).value);
        System.out.println(new ConstructorReturnDemo(false).value);
    }
}
